test.use({ viewport: { width: 1280, height: 720 } });

test('Invoice confirmation', async ({ page }) => {
  const consoleErrors: string[] = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });

  await page.goto('/invoice.html');
  // recorded action 1: click "Pay this invoice"
  await page.getByTestId('pay-invoice').click();
  // recorded action 2: fill "Name on card"
  await page.getByRole('textbox', { name: 'Name on card' }).fill('example'); // replaytest-marker: placeholder-value — placeholder value
  // recorded action 3: fill "Billing email (for your receipt)"
  await page.getByRole('textbox', { name: 'Billing email (for your receipt)' }).fill('test@example.com'); // replaytest-marker: placeholder-value — placeholder value
  // TODO masked field not in the recording, supply a test value
  // await page.getByLabel('Card number').fill('<supply test value>'); // label inferred from adjacent text — verify the locator resolves
  // recorded action 4: click "Submit payment"
  await page.getByTestId('submit-payment').click();

  await expect(page).toHaveURL('/invoice-confirmation.html');
  await expect(page).toHaveTitle('Payment Successful');
  expect(consoleErrors).toEqual([]); // replaytest-marker: console-clean — witnessed-clean: the session recording confirms 0 console errors
});
